package com.yeyamo_mobile.api.discovery_service.infrastructure.maps;
import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.*;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.discovery_service.application.maps.*;import com.yeyamo_mobile.api.discovery_service.application.port.ExternalMapsPort;
@Component public class GoogleMapsAdapter implements ExternalMapsPort{private final RestClient geocoding;private final RestClient routes;private final GoogleMapsProperties properties;public GoogleMapsAdapter(GoogleMapsProperties properties){this.properties=properties;geocoding=RestClient.builder().baseUrl(properties.baseUrl()).requestFactory(factory()).build();routes=RestClient.builder().baseUrl(properties.routesBaseUrl()).requestFactory(factory()).build();}public GeocodeResult geocode(String address){JsonNode root=execute(()->geocoding.get().uri(uri->uri.path("/maps/api/geocode/json").queryParam("address",address).queryParam("key",properties.apiKey()).build()).retrieve().body(JsonNode.class));return mapGeocode(root);}public GeocodeResult reverseGeocode(Coordinate coordinate){JsonNode root=execute(()->geocoding.get().uri(uri->uri.path("/maps/api/geocode/json").queryParam("latlng",coordinate.latitude()+","+coordinate.longitude()).queryParam("key",properties.apiKey()).build()).retrieve().body(JsonNode.class));return mapGeocode(root);}public RouteResult route(Coordinate origin,Coordinate destination,TravelMode mode){Map<String,Object>body=Map.of("origin",waypoint(origin),"destination",waypoint(destination),"travelMode",mode.name(),"polylineQuality","OVERVIEW");JsonNode root=execute(()->routes.post().uri("/directions/v2:computeRoutes").contentType(MediaType.APPLICATION_JSON).header("X-Goog-Api-Key",properties.apiKey()).header("X-Goog-FieldMask","routes.distanceMeters,routes.duration,routes.polyline.encodedPolyline").body(body).retrieve().body(JsonNode.class));JsonNode route=root==null?null:root.path("routes").path(0);if(route==null||route.isMissingNode())throw new ExternalMapsException("LOCATION_NOT_FOUND","Aucun itinéraire disponible",HttpStatus.NOT_FOUND);return new RouteResult(route.path("distanceMeters").asLong(),durationSeconds(route.path("duration").asText()),route.path("polyline").path("encodedPolyline").asText(),origin,destination);}private Map<String,Object>waypoint(Coordinate c){return Map.of("location",Map.of("latLng",Map.of("latitude",c.latitude(),"longitude",c.longitude())));}private GeocodeResult mapGeocode(JsonNode root){String status=root==null?null:root.path("status").asText();if("ZERO_RESULTS".equals(status))throw new ExternalMapsException("LOCATION_NOT_FOUND","Adresse introuvable",HttpStatus.NOT_FOUND);if(!"OK".equals(status))throw providerStatus(status);JsonNode first=root.path("results").path(0);JsonNode location=first.path("geometry").path("location");Map<String,String>components=new LinkedHashMap<>();for(JsonNode component:first.path("address_components")){String value=component.path("long_name").asText();for(JsonNode type:component.path("types"))components.putIfAbsent(type.asText(),value);}return new GeocodeResult(first.path("formatted_address").asText(),location.path("lat").asDouble(),location.path("lng").asDouble(),first.path("place_id").asText(),components);}private <T>T execute(java.util.function.Supplier<T> call){for(int attempt=1;;attempt++){try{return call.get();}catch(HttpClientErrorException e){if(e.getStatusCode().value()==429&&attempt<3)continue;throw httpError(e.getStatusCode());}catch(HttpServerErrorException e){if(attempt<3)continue;throw httpError(e.getStatusCode());}catch(ResourceAccessException e){throw new ExternalMapsException("MAPS_PROVIDER_UNAVAILABLE","Service cartographique temporairement indisponible",HttpStatus.SERVICE_UNAVAILABLE);}}}private ExternalMapsException providerStatus(String status){return switch(String.valueOf(status)){case"REQUEST_DENIED"->new ExternalMapsException("MAPS_PROVIDER_FORBIDDEN","Service cartographique non autorisé",HttpStatus.FORBIDDEN);case"OVER_QUERY_LIMIT"->new ExternalMapsException("MAPS_RATE_LIMITED","Service cartographique temporairement limité",HttpStatus.TOO_MANY_REQUESTS);default->new ExternalMapsException("MAPS_PROVIDER_UNAVAILABLE","Service cartographique temporairement indisponible",HttpStatus.SERVICE_UNAVAILABLE);};}private ExternalMapsException httpError(HttpStatusCode status){if(status.value()==403)return providerStatus("REQUEST_DENIED");if(status.value()==429)return providerStatus("OVER_QUERY_LIMIT");if(status.is4xxClientError())return new ExternalMapsException("INVALID_REQUEST","Requête cartographique invalide",HttpStatus.BAD_REQUEST);return new ExternalMapsException("MAPS_PROVIDER_UNAVAILABLE","Service cartographique temporairement indisponible",HttpStatus.SERVICE_UNAVAILABLE);}private long durationSeconds(String duration){try{return Math.round(Double.parseDouble(duration.replace("s","")));}catch(Exception e){return 0;}}private org.springframework.http.client.SimpleClientHttpRequestFactory factory(){var factory=new org.springframework.http.client.SimpleClientHttpRequestFactory();factory.setConnectTimeout(5000);factory.setReadTimeout(10000);return factory;}}
